const isObject = body !== null && typeof body === 'object' && !Array.isArray(body);
const fields = ['request_id', 'query', 'type', 'access_levels', 'top_k'];
const received = {};
for (const field of fields) received[field] = isObject && Object.prototype.hasOwnProperty.call(body, field) ? body[field] : null;
const invalid_fields = [];
if (!isObject) invalid_fields.push('body');
if (typeof received.request_id !== 'string' || received.request_id.length < 1 || received.request_id.length > 64) invalid_fields.push('request_id');
if (typeof received.query !== 'string' || received.query.trim().length === 0) invalid_fields.push('query');
if (typeof received.type !== 'string' || received.type.trim().length === 0) invalid_fields.push('type');
const levels = received.access_levels;
const validLevels = Array.isArray(levels) && (levels.length === 1 && levels[0] === 'all' || levels.length === 2 && levels[0] === 'all' && levels[1] === 'it');
if (!validLevels) invalid_fields.push('access_levels');
if (received.top_k !== 3) invalid_fields.push('top_k');
const valid = invalid_fields.length === 0;
return [{ json: { step: 'P1-2 STEP 3', mock: true, diagnostic_only: true, body_is_object: isObject, valid, invalid_fields, received: valid ? received : null, access_authorization: valid && levels.length === 2 ? 'it_unverified' : 'not_verified', it_access_granted: false, search_eligible: valid && levels.length === 1, search_executed: false, http_status: valid ? 200 : 400 } }];

