// Mock only: lexical overlap, no embedding/vector similarity.
function authorize(x) { return x.valid === true && x.search_eligible === true && x.received.access_levels.length === 1 && x.received.access_levels[0] === 'all'; }
function encodeQuery(query) { return [...new Set(query.toLowerCase().trim().split(/\s+/))]; }
function allowedCandidates(rows) { return rows.filter(r => r.access_level === 'all'); }
function rank(rows, terms) { return rows.map(r => ({...r, score: terms.filter(t => (r.title+' '+r.text).toLowerCase().includes(t)).length / terms.length})).filter(r => r.score > 0).sort((a,b) => b.score-a.score || (a.doc < b.doc ? -1 : a.doc > b.doc ? 1 : a.chunk_no-b.chunk_no)).slice(0,3); }
function response(rows) { return {ok:true,evidence:rows.map(r=>({doc:r.doc,section:r.section,text:r.text,score:r.score})),reason:rows.length ? null : 'no_evidence'}; }
if (!authorize(input)) return [{json:{http_status:input.http_status,response:input}}];
try {
 const query = input.received.query;
 // Explicit synthetic fault query, available only in this Mock workflow.
 if (query === '__mock_search_unavailable__') throw new Error('synthetic_fault');
 const selected = rank(allowedCandidates(fixture), encodeQuery(query));
 return [{json:{http_status:200,response:response(selected),mock:true,ranking:'lexical_overlap_not_cosine',selected_metadata:selected.map(({text,...metadata})=>metadata)}}];
} catch (_) { return [{json:{http_status:503,response:{ok:false,evidence:[],reason:'search_unavailable'},mock:true}}]; }
